namespace PhotoStudio.Application.Portal.SubmitProof;

/// <summary>
/// Command for the client to report a SINPE Móvil transfer for the photographer to verify (B3).
/// </summary>
/// <param name="Token">Secret token taken from the URL.</param>
/// <param name="AuthorizedBookingId">Booking the portal session is valid for; it must be the booking of the link.</param>
/// <param name="Amount">Amount transferred.</param>
/// <param name="Reference">Reference (confirmation number) of the transfer, optional.</param>
/// <param name="IdempotencyKey">Key generated by the portal so a double click or a retry registers the proof once.</param>
public sealed record SubmitPortalPaymentProofCommand(
    string Token,
    Guid AuthorizedBookingId,
    decimal Amount,
    string? Reference,
    string IdempotencyKey);
